const TOP_CHAINS = 10;
const TOP_MODELS = 5;

const num = v => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};
// HTML escaping for Telegram (no backslashes)
const esc = s => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');
const tok = n =>
  n >= 1e6 ? (n / 1e6).toFixed(2) + 'M' :
  n >= 1e3 ? (n / 1e3).toFixed(1) + 'K' : String(n);
const usd = c =>
  c >= 1 ? '$' + c.toFixed(2) :
  c >= 0.01 ? '$' + c.toFixed(3) : '$' + c.toFixed(4);

const collect = items => {
  const out = [];
  for (const item of items) {
    const j = item.json || {};
    if (Array.isArray(j.runs)) out.push(...j.runs);
    else if (j.run_type || j.name) out.push(j);
  }
  return out;
};

const rootRuns = collect($('Query LangSmith Runs (24h)').all());
const llmRuns = collect($input.all());

const now = Date.now();
const cutoff = now - 24 * 60 * 60 * 1000;
const inWindow = r => {
  const t = new Date(r.start_time).getTime();
  return Number.isFinite(t) && t >= cutoff && t <= now;
};

const getStats = r => {
  const usage = r.extra?.usage_metadata || {};
  const prompt = num(r.prompt_tokens ?? usage.input_tokens);
  const completion = num(r.completion_tokens ?? usage.output_tokens);
  const tokens = num(r.total_tokens ?? usage.total_tokens ?? (prompt + completion));
  let cost = 0;
  if (r.total_cost != null) cost = num(r.total_cost);
  else if (r.prompt_cost != null || r.completion_cost != null)
    cost = num(r.prompt_cost) + num(r.completion_cost);
  return { prompt, completion, tokens, cost };
};

const add = (map, key, s) => {
  const g = map.get(key) || { count: 0, prompt: 0, completion: 0, tokens: 0, cost: 0 };
  g.count++; g.prompt += s.prompt; g.completion += s.completion;
  g.tokens += s.tokens; g.cost += s.cost;
  map.set(key, g);
};

// --- Chains ---
const byChain = new Map();
let totalPrompt = 0, totalCompletion = 0, totalTokens = 0, totalCost = 0;
const roots = rootRuns.filter(inWindow);

for (const r of roots) {
  const s = getStats(r);
  totalPrompt += s.prompt; totalCompletion += s.completion;
  totalTokens += s.tokens; totalCost += s.cost;
  add(byChain, r.name || 'Unknown chain', s);
}

// --- Models ---
const byModel = new Map();
for (const r of llmRuns.filter(inWindow)) {
  const meta = r.extra?.metadata || {};
  const params = r.extra?.invocation_params || {};
  const model = meta.ls_model_name || params.model || params.model_name || 'Unknown model';
  const provider = meta.ls_provider || 'unknown';
  add(byModel, `${provider} / ${model}`, getStats(r));
}

const sorted = map => [...map.entries()].sort((a, b) => b[1].tokens - a[1].tokens);

// Full chain name, no truncation and no slashes
const chainLabel = full => `<b>${esc(full)}</b>`;

// "openai / gpt-4.1" -> "gpt-4.1"
const modelLabel = full => esc(full.split(' / ').slice(1).join(' / ') || full);

const restLine = (entries, top) => {
  const rest = entries.slice(top);
  if (!rest.length) return '';
  const t = rest.reduce((a, [, s]) => a + s.tokens, 0);
  const c = rest.reduce((a, [, s]) => a + s.cost, 0);
  return `\n…и ещё ${rest.length}: ${tok(t)} tok · ${usd(c)}`;
};

const chains = sorted(byChain);
const models = sorted(byModel);

const chainText = chains.slice(0, TOP_CHAINS).map(([name, s]) =>
  `• ${chainLabel(name)}\n  ${s.count} запусков · ${tok(s.tokens)} tok · ${usd(s.cost)}`
).join('\n') + restLine(chains, TOP_CHAINS);

const modelText = models.slice(0, TOP_MODELS).map(([name, s]) =>
  `• <b>${modelLabel(name)}</b>: ${s.count} вызовов · ${tok(s.tokens)} tok (in ${tok(s.prompt)} / out ${tok(s.completion)}) · ${usd(s.cost)}`
).join('\n') + restLine(models, TOP_MODELS);

const text = [
  '📊 <b>LangSmith за 24 часа</b>',
  `💰 <b>${usd(totalCost)}</b> · ${tok(totalTokens)} tok · ${roots.length} запусков`,
  `in ${tok(totalPrompt)} / out ${tok(totalCompletion)}`,
  '',
  '<b>Цепочки</b>',
  chainText || 'Нет данных',
  '',
  '<b>Модели</b>',
  modelText || 'Нет данных'
].join('\n');

return [{ json: { text, runsCount: roots.length, totalTokens, totalCost } }];
